SELECT 

AND (#{afterId} IS NULL OR pb.product_id < #{afterId})
ORDER BY pb.product_id DESC LIMIT #{limit}

, matched_products AS ( SELECT product_id, MAX(discovery_rank) AS discovery_rank FROM ( SELECT candidate.id AS product_id, CASE WHEN candidate.name = #{filter.keyword} THEN 4 ELSE 3 END AS discovery_rank FROM products candidate WHERE
UNION ALL SELECT pb.product_id, 2 FROM brands candidate JOIN product_brands pb ON pb.brand_id = candidate.id WHERE candidate.enabled = 1 AND
UNION ALL SELECT product.id, 2 FROM shops candidate JOIN products product ON product.shop_id = candidate.id WHERE candidate.enabled = 1 AND
) hits GROUP BY product_id )
SELECT ,
matched.discovery_rank 0 AS discoveryRank
JOIN matched_products matched ON matched.product_id = p.id
AND (matched.discovery_rank < #{afterRank} OR (matched.discovery_rank = #{afterRank} AND p.id < #{afterId}))
AND p.id < #{afterId}
ORDER BY matched.discovery_rank DESC, p.id DESC LIMIT #{limit}
